// Authored fiction based on the three Team 12 presentation scenarios.
// Flags describe this story world. They are not measured effects or ethical scores.
export const chapters = [
  {id:'tim',person:'Tim',role:'Order picker',number:'01',title:'The cost of keeping up',theme:'Pressure & cooperation',time:'08:00',hook:'A leaderboard has turned the picking floor into a race.',intro:'Tim delays water breaks, stops helping new coworkers, and keeps checking his hourly rank. His shoulders ache. You have one shift to change what the warehouse rewards.',first:'t-plan'},
  {id:'priya',person:'Priya',role:'Tote handler',number:'02',title:'When safety becomes scrutiny',theme:'Safety & purpose limits',time:'13:15',hook:'A near miss opens a door into someone’s whole working day.',intro:'An AMR moves before Priya finishes unloading. She presses the emergency stop. A “handoff complete” signal arrived too early. Her manager wants every location and handoff from her shift.',first:'p-stop'},
  {id:'tom',person:'Tom',role:'Warehouse associate',number:'03',title:'The report he never saw',theme:'Notice & fair evaluation',time:'16:30',hook:'A hidden report has already cost Tom his job.',intro:'Tom was told the robots would help with picking. A month later, an undisclosed individual-output report was used to dismiss him. He worries about supporting his wife and child. You receive his request for a review.',first:'m-appeal'}
];
export const chapterById = id => chapters.find(c=>c.id===id);
export const policyNames = {allowed:'Within the proposal',review:'Needs further safeguards',violation:'Outside the proposal'};
const c=(id,label,detail,patch,event,policy,why,tradeoff='')=>({id,label,detail,patch,event,policy,why,tradeoff});
const scene=(id,chapter,title,prompt,choices,next,extra={})=>({id,chapter,title,prompt,choices,next,...extra});
const slotCount=n=>`${n} ${n===1?'slot':'slots'}`;
const evidence=(id,label,detail)=>({id,label,detail});
const allocation=(id,chapter,title,prompt,items,next,apply)=>scene(id,chapter,title,prompt,[],next,{type:'allocation',items,apply});
const pickRecords=(id,chapter,title,prompt,records,next,apply,min=1,max=records.length)=>scene(id,chapter,title,prompt,[],next,{type:'records',records,min,max,apply});

export const scenes = [
  allocation('t-plan','tim','You have three planning slots. Where do they go?',
    'The dispatch board is full. Assign up to three fictional planning slots across today’s improvements. Basic breaks and safety remain available regardless of your allocation. A slot represents attention and preparation, not money or a measured performance benefit.',[
      evidence('coverage','Break coverage','Prepare a relief plan so a worker can leave the station.'),
      evidence('routing','Queue coordination','Give someone time to investigate the blocked aisle.'),
      evidence('mentoring','New-worker support','Make training and helping part of the shift plan.')
    ],'t-board',(a)=>({patch:{tCoverage:a.coverage>0,tRouting:a.routing>0,tMentorPlan:a.mentoring>0,tPlan:{...a}},event:`Your shift plan assigns ${slotCount(a.coverage)} to coverage, ${a.routing} to queues, and ${a.mentoring} to mentoring. The preparation board now records where support is ready and where the team will have to react.`,policy:'review',why:'This resource puzzle illustrates operational preparation. The proposed monitoring ban alone does not supply staffing or ergonomic support.',tradeoff:'Concentrating the plan leaves another part of the shift to handle reactively.'})),
  scene('t-board','tim','The screen everyone keeps watching',
    'The public board gives bonuses to the top pickers and warnings to those at the bottom. Tim glances up before reaching for his water bottle. What replaces the board?',[
      c('public','Keep the public ranking','It gives supervisors an immediate comparison.',{tMonitor:'public',everMonitoring:true},'The ranking stays bright. Tim puts the bottle down and returns to picking.','violation','Public, continuous individual productivity records cross the team’s proposed boundary. The display also creates an incentive to sacrifice uncounted activities.'),
      c('private','Move the ranking into the supervisor’s office','Workers stop seeing it, but the individual history remains.',{tMonitor:'private',everMonitoring:true},'The floor display goes blank. In the office, the same individual history continues to grow.','violation','Making the audience smaller does not change the purpose or continuity of the identifiable productivity history.'),
      c('workflow','Show workflow totals and blocked aisles','Keep active-task coordination without a continuing individual rank.',{tMonitor:'off'},'The names disappear. The board now shows where work is waiting, leaving the team to decide how to cover it.','allowed','Necessary coordination and aggregate operations can remain. Later scenes test whether those totals can still identify a worker.','Supervisors lose a convenient individual comparison and need another way to understand delays.')
    ],'t-queue'),
  scene('t-queue','tim','Aisle C is backing up',
    w=>w.tRouting?'Your queue coordinator finds two carts blocking the same handoff. Dispatch asks whether to reroute or push individual targets.':'No one was assigned to inspect the queue. Two carts now block a handoff. Dispatch wants a fast response.',[
      c('reroute','Reroute active tasks around the blockage','Accept a detour and keep only current assignment information.',{tQueue:'managed'},'The route line bends around Aisle C. Orders still wait, but the team can see the obstruction.','allowed','Active-task routing is an operational use. It does not require a lasting worker productivity profile.','The detour consumes attention and may delay some orders in this fictional shift.'),
      c('target','Tell the bottom-ranked pickers to catch up','Use individual pace comparisons to clear the queue.',{tQueue:'pressured',tMonitor:'private',everMonitoring:true},'The carts stay where they are. A private list of “slow” pickers begins circulating.','violation','An operational delay does not authorize a continuous individual pace comparison. The queue also gives a competing explanation for lower output.'),
      c('wait','Leave assignments unchanged','Keep the data restriction and let the queue work itself out.',{tQueue:'blocked'},'The route remains blocked. Tim waits behind a cart while dispatch asks why the totals have fallen.','review','Restricting monitoring does not by itself resolve congestion. A policy-compliant data setting can coexist with weak operations.')
    ],'t-break'),
  scene('t-break','tim','Tim asks for water',
    w=>w.tCoverage?'A relief plan is ready. Tim asks to leave his station for water.':'Tim asks for water. There is no prepared cover plan, so you need to adapt the queue.',[
      c('cover','Protect the break and cover the station','Use the relief plan, or temporarily pause and reassign active tasks.',{tBreak:true},'Tim walks to the break station. A task is reassigned instead of becoming a mark against his pace.','allowed','The game preserves breaks without requiring individual productivity histories. Staffing and ergonomic protections extend beyond the monitoring rule.','Without prepared coverage, dispatch must absorb a temporary interruption.'),
      c('later','Ask him to wait until the next target is met','The queue gets first claim on his time.',{tBreak:false},'The break-room light stays off. Tim checks the board before answering.','review','The monitoring proposal does not alone settle every break or workload decision. This branch shows a pressure problem that may persist even after a display is removed.'),
      c('track','Allow the break but add it to his output profile','Record the delay as part of a continuing individual comparison.',{tBreak:true,tMonitor:'private',everMonitoring:true},'Tim gets water. The supervisor adds a new line to his individual pace history.','violation','A break does not justify extending an individually identifiable productivity dossier.')
    ],'t-help'),
  scene('t-help','tim','A new coworker is stuck',
    'A new picker cannot complete a tote handoff. Tim knows how to help, but assisting will lower the time he spends on his own picks. How does the shift treat that work?',[
      c('shared','Make helping part of the assignment','Reassign active tasks and include mentoring in the team’s work.',{tHelp:true},'Tim steps across the aisle. The new picker finishes the handoff with him instead of working around the problem alone.','allowed','Cooperation is relevant context that individual pick counts can omit. Active assignments can acknowledge it without retaining a pace ranking.'),
      c('own','Tell Tim to protect his own number','The new picker should wait for the designated trainer.',{tHelp:false},'Tim turns back to his tote. The new picker waits while an unfinished handoff occupies the lane.','review','A ban on surveillance does not automatically reward cooperation. Assignment rules and training resources also shape the outcome.'),
      c('credit','Give Tim a permanent “helpfulness” score','Combine it with every worker’s hourly productivity record.',{tHelp:true,tMonitor:'private',everMonitoring:true},'The handoff is completed, and a second individual score is added beside Tim’s pace.','violation','Adding context does not authorize a continuing identifiable AMR productivity evaluation. A richer dossier can still cross the same boundary.')
    ],'t-bonus'),
  scene('t-bonus','tim','The weekly bonus is due',
    'The old bonus rewards the highest individual pick count. A supervisor says removing it will leave good work unrecognized.',[
      c('context','Pause the AMR ranking and review work with context','Include difficult tasks, training, quality, and worker accounts.',{tBonus:'context'},'The bonus decision waits for a contextual review. Tim’s time helping the new picker enters the discussion.','allowed','The proposal limits AMR-based individual histories. It leaves room for justified recognition using fair, contextual processes.','A slower review needs judgment and a way to challenge supervisor bias.'),
      c('team','Reward a shared target without individual AMR histories','Keep a route for workers to challenge team pressure.',{tBonus:'team'},'The individual race ends. Workers immediately ask what happens when one blocked aisle holds back the whole team.','review','Team incentives can reduce individual exposure but still create collective pressure. Aggregate data is not a complete account of fair incentives.'),
      c('rank','Keep the bonus and disclose the ranking','Explain the scoring at the next briefing.',{tBonus:'rank',tMonitor:'public',everMonitoring:true},'The scoring is explained clearly. The same individual race remains.','violation','Notice is a separate requirement. It does not permit the continuous monitoring the proposal prohibits.')
    ],'t-export'),
  scene('t-export','tim','A spreadsheet arrives from dispatch',
    'The file has robot numbers and completed loads but no employee-ID column. One robot has stayed with Tim all shift. A supervisor asks you to approve the dashboard.',[
      c('test','Check whether an observer can infer the worker','Compare robot assignments with the supposedly anonymous totals.',{tReidTest:true,tReidLeak:true},'You put the assignment sheet next to the load totals. The supervisor can point to Tim without needing his employee ID.','allowed','Identifiability depends on context and linkage, not only whether a name column is present.'),
      c('approve','Approve it because the employee-ID column is gone','Leave robot-by-robot output visible to operations managers.',{tReidLeak:true},'The dashboard uses robot numbers. Everyone on the floor still knows which one has been following Tim.','violation','Stable robot assignments can turn operational counts into an identifiable worker output history. The game treats that actual use as crossing the boundary.'),
      c('remove','Turn off all current robot assignment information','Avoid linkage by removing even the active handoff view.',{tTaskBlind:true},'The individual comparison disappears, along with information dispatch needs to coordinate the next handoff.','review','The proposal explicitly allows minimum information necessary for an active task. Blanket removal can obstruct legitimate coordination.')
    ],w=>w.tReidTest?'t-reid':'t-voice'),
  scene('t-reid','tim','The names are gone. Tim is still visible.',
    'Robot 07 is assigned to one worker. Showing its whole-shift load total would reveal that worker’s output. Choose the redesign you will actually implement.',[
      c('broader','Show broader workflow totals and separate access','Keep current-task links only where necessary, then test the released view again.',{tReidLeak:false,tTaskBlind:false},'The dashboard follows the workflow, not Robot 07’s whole-shift count. You leave a check for reconstructing a person’s record.','allowed','Broader summaries and access separation can reduce linkage. The adequacy of a specific view still requires a contextual re-identification check.'),
      c('code','Rename Robot 07 to a random code','Keep the same one-worker assignment and whole-shift count.',{tReidLeak:true},'The label changes. The association is still obvious to the supervisor who assigned the robot.','violation','Pseudonyms do not prevent inference when the observer already knows the assignment.'),
      c('trust','Keep the view and ask supervisors not to infer names','Rely on a rule without changing access or review.',{tReidLeak:true},'A reminder goes out. The reconstruction remains one glance away.','violation','A warning alone leaves identifiable productivity monitoring available to the same audience.')
    ],'t-voice'),
  scene('t-voice','tim','“Will this come back in my review?”',
    w=>w.tBreak&&w.tHelp?'After his break, Tim asks whether helping the new picker can still count against him later.':'Tim asks for a private conversation. He is unsure whether reporting discomfort or helping someone will appear in a later review.',[
      c('listen','Invite his account and record the policy concern','Provide a route to challenge data use without retaliation.',{tVoice:true,workerVoice:true},'Tim describes how the ranking changed his breaks and cooperation. His account becomes part of the redesign.','allowed','Notice, access restrictions, and remedies need a usable worker-facing process. This dialogue explores an implementation of that requirement.'),
      c('reassure','Say the dashboard has been fixed and return to work','Do not create a review or challenge process.',{tVoice:false},'Tim nods, but keeps the question to himself. The settings have changed more than the conversation.','review','A technical change does not establish that workers can question past or future uses.'),
      c('flag','Mark him as resistant to performance management','Keep the comment with his AMR output record.',{tVoice:false,tMonitor:'private',everMonitoring:true},'His question is copied into an individual performance file. He stops describing what happened.','violation','Using the report to expand an AMR-linked productivity dossier defeats the proposal’s boundary and weakens the reporting process.')
    ],'t-contract'),
  scene('t-contract','tim','Make it last beyond your shift',
    'The fleet supplier offers to disable individual histories, but says linked exports and supervisor permissions need separate configuration. What do you sign off?',[
      c('enforce','Disable the history and linked exports, then verify access','Assign responsibility for checking that the change holds.',{tMonitor:'off',tEnforce:true},'The export test fails for the operations role. Someone is named to check it again after software changes.','allowed','The policy covers fleet software and linked systems. Checking actual access makes the restriction more concrete than a promise.'),
      c('memo','Send a policy memo while leaving the old access enabled','Rely on supervisors to avoid the feature.',{tEnforce:false},'The memo is pinned beside a workstation that can still open the old report.','review','A written boundary needs workable access controls and enforcement. The memo alone does not demonstrate either.'),
      c('offall','Disconnect all operational records','Remove current assignments along with histories.',{tMonitor:'off',tTaskBlind:true,tEnforce:true},'The records stop. Dispatch loses the active-task view and begins coordinating around the software.','review','A data restriction that blocks permitted necessary operations creates a different problem and may encourage workaround systems.')
    ],'t-close'),
  scene('t-close','tim','The last tote of the morning',
    'A few orders are still waiting. You can carry your current approach forward, make one explicit repair, or reopen the old ranking for the next team.',[
      c('carry','Hand over the policy, open problems, and worker accounts','Keep both improvements and unresolved issues visible.',{tHandover:true},'The next manager receives the route changes, the data boundary, and Tim’s account. The waiting orders are still on the board.','allowed','A documented handover makes outstanding operational and accountability questions visible without rebuilding a worker ranking.'),
      c('repair','Make a late repair to access and break protection','Stop current individual histories and protect breaks now.',{tMonitor:'off',tBreak:true,tEnforce:true,tLateRepair:true},'The old feed is disabled before handover. Tim gets protection now, though it cannot erase what happened earlier.','allowed','A later repair can improve current practice. Earlier collection and decisions still need their own remedy.'),
      c('reopen','Restore the individual ranking for tomorrow’s target','Promise to revisit it after the busy period.',{tMonitor:'public',everMonitoring:true},'The next shift’s display lights up with names again. The temporary exception has acquired another day.','violation','A busy period does not suspend the proposed prohibition on continuous identifiable productivity monitoring.')
    ],null),

  scene('p-stop','priya','The emergency stop is still pressed',
    w=>w.tVoice?'Priya has heard that Tim was allowed to challenge the dashboard. She gives you a careful account of the moving tote. Dispatch asks to restart.':'Priya reports that the robot moved while she was unloading. She pauses before adding details. Dispatch asks to restart.',[
      c('isolate','Keep the affected handoff stopped and preserve the event','Use an alternate workflow while the designated team investigates.',{pIsolate:true},'The affected robot stays still. Priya steps clear, and dispatch marks an alternate route.','allowed','The proposal preserves safety operations and incident-specific investigation. This scene is not an instruction for clearing a physical robot for use.','The affected station is unavailable while the fictional investigation proceeds.'),
      c('restart','Restart after a quick look','Collect more evidence later.',{pIsolate:false},'The robot returns to the route. The unexplained signal remains in the event log.','review','A monitoring rule does not establish a safe restart procedure. The story carries the unresolved technical issue forward.'),
      c('replace','Move Priya away and request her whole shift history','Treat the incident as a possible worker pace problem.',{pIsolate:false,pBroad:true,everMisuse:true},'Priya leaves the station. Her location history enters the review before the signal has been explained.','violation','The exception is for the minimum identifiable information necessary to resolve a specific safety question. A general pace inquiry does not meet that purpose.')
    ],'p-plan'),
  allocation('p-plan','priya','Plan the investigation without abandoning the floor',
    'Assign up to three planning slots. Essential isolation and a justified review remain available even if you assign no slot. The allocation changes how much support is prepared around them.',[
      evidence('alternate','Alternate workflow','Prepare a route while the affected handoff is out of use.'),
      evidence('reviewer','Request review','Give a designated reviewer time to inspect purpose and scope.'),
      evidence('validation','Follow-up testing','Prepare a supervised technical check before any operational release.')
    ],'p-records',a=>({patch:{pAlternate:a.alternate>0,pReviewer:a.reviewer>0,pValidation:a.validation>0,pPlan:{...a}},event:'The alternate lane, review desk, and testing area receive the support you assigned. Unplanned preparations will need an explicit response later.',policy:'review',why:'Organizational capacity affects whether a narrow-access policy can be implemented. These planning slots are fictional and do not price worker rights.'})),
  pickRecords('p-records','priya','Build the first evidence packet',
    'Choose two or three records to examine first. The event occurred at 13:14. The question is why the robot received a completion signal before unloading had finished.',[
      evidence('robot','Robot event window','13:13–13:15, motion state and received completion signal. No worker name.'),
      evidence('signal','Redacted handoff trace','Task and signal sequence around 13:14. Worker identifiers removed.'),
      evidence('account','Priya’s event account','Her account of the unloading sequence and emergency stop.'),
      evidence('shift','Full individual shift history','Every location and handoff from the working day.')
    ],'p-question',a=>({patch:{pRobot:a.includes('robot'),pTrace:a.includes('signal'),pAccount:a.includes('account'),pBroad:a.includes('shift')},event:a.includes('shift')?'The packet includes the whole working day. The narrow event is now surrounded by unrelated information.':'The packet is limited to the event. What it can explain depends on the records you selected.',policy:a.includes('shift')?'violation':'allowed',why:a.includes('shift')?'An entire identifiable shift is not justified by starting with a general incident. The request must establish necessity for each field and time window.':'Starting with non-identifying event records follows Strategy 3. A worker’s voluntary account can add context without releasing their whole history.'}),2,3),
  scene('p-question','priya','Write the question before requesting more',
    w=>w.pRobot&&w.pTrace?'The packet locates the premature completion signal. It still needs a link to the active handoff that produced it.':'The initial packet is incomplete. A manager proposes using the gap to ask for every handoff Priya completed today.',[
      c('specific','Ask which active handoff produced the premature signal','Check redacted event sources before considering identity.',{pQuestion:'specific'},'The request names the signal at 13:14 and asks what minimum link would explain it.','allowed','An unresolved safety question should be specific enough to test whether additional identifiable information is necessary.'),
      c('suspicion','Ask whether Priya is generally slower than other workers','Use her pace as the reason the safety inquiry is unresolved.',{pQuestion:'pace',pBroad:true,everMisuse:true},'The incident form now asks for a shift-wide comparison. The signal question has changed into a performance question.','violation','A suspicion about general pace cannot convert a safety exception into authorization for productivity monitoring.'),
      c('collect','Request everything now and decide relevance later','Let the investigator choose after receiving the file.',{pQuestion:'all',pBroad:true},'The reviewer receives an open-ended request with no field or time limit.','violation','Minimum necessary access requires establishing scope before release, not filtering after unrestricted disclosure.')
    ],'p-access'),
  scene('p-access','priya','The identifiable-record gate',
    w=>w.pQuestion==='specific'?'The reviewer can first request the missing redacted sources. If they still leave a specific link unresolved, a two-minute task-to-operator link may be considered.':'The current request does not establish a narrow unresolved safety question. Decide whether to repair it or release records anyway.',[
      c('redacted','Complete the non-identifying packet first','Request the robot window and redacted signal sequence.',{pRobot:true,pTrace:true,pAccess:'redacted'},'The event window and signal sequence arrive without a worker history. You can now inspect the mismatch.','allowed','Non-identifying sources come first. A later identity request needs its own specific necessity argument.'),
      c('request','Submit a two-minute identity-link request for review','Specify the question, missing link, fields, audience, and expiry.',{pAccess:'requested'},'The request goes to a separate review desk. No identifiable record has been released yet.','review','A narrow time window alone is insufficient. The reviewer must also establish the safety purpose, prior checks, and why identity is needed.'),
      c('full','Release Priya’s full shift to the supervisor','Rely on the documented incident as the authorization.',{pAccess:'full',pBroad:true,everMisuse:true},'A whole-shift file arrives in the supervisor’s inbox. It can answer many questions that the incident never raised.','violation','Documenting an incident does not justify every identifiable record related to the worker.')
    ],w=>w.pAccess==='requested'?'p-review':'p-trace'),
  scene('p-review','priya','You are the designated reviewer',
    w=>w.pQuestion==='specific'&&w.pRobot&&w.pTrace?'The request identifies a specific remaining active-handoff link and documents the redacted checks. The proposed release is limited to that event.':'The request is missing a specific safety question or prior redacted checks. “Only two minutes” does not fix that omission.',[
      c('conditional','Apply the gate to this request','Authorize only if the specific question and prior checks establish necessity.',w=>({pAuthorized:w.pQuestion==='specific'&&w.pRobot&&w.pTrace,pGate:true,pRobot:true,pTrace:true,pRejected:!(w.pQuestion==='specific'&&w.pRobot&&w.pTrace)}),w=>w.pAuthorized?'The reviewer releases only the event-specific link with restricted recipients and a documented purpose.':'The request is refused as submitted. The reviewer sends the investigation back to the redacted event sources.','allowed','A designated reviewer applies necessity before disclosure. Rejection is a real possible outcome, not an automatic signature.'),
      c('rubber','Approve because an incident was reported','Treat the event number as enough.',{pAuthorized:true,pGate:false,everMisuse:true},'The incident number substitutes for a necessity decision. The exception is now easier to invoke than to challenge.','violation','Authorization needs an unresolved safety question and minimum necessary scope. A qualifying incident is only the starting condition.'),
      c('never','Refuse every identity link in every case','Do not complete the non-identifying checks either.',{pAuthorized:false,pGate:false,pEvidenceBlind:true},'The cabinet remains closed. The investigation also stops asking the event questions still available without identity.','review','The proposal allows justified minimum identifiable access. A blanket refusal can leave a legitimate safety question unresolved.')
    ],'p-trace'),
  scene('p-trace','priya','A signal arrives before the tote is clear',
    w=>w.pRobot&&w.pTrace?'In this synthetic packet, the event sequence shows an earlier completion message being accepted during the current handoff. Priya’s pace does not explain that ordering. A competent technical team still needs to validate the diagnosis.':'You have no complete event-and-signal sequence. The full shift history, if you requested it, does not fill that technical gap.',[
      c('trace','Complete the event trace and send it for technical validation','Document the premature message and the remaining uncertainty.',{pRobot:true,pTrace:true,pDiagnosis:true},'The case board now points to the handoff sequence. The investigation has a technical question it can actually test.','allowed','The fictional evidence supports an event-specific inquiry. It does not establish a real robot failure mode or provide a physical repair procedure.'),
      c('pace','Conclude that Priya worked too slowly','Close the inquiry as a worker performance issue.',{pDiagnosis:false,pPace:true,everMisuse:true},'The case label changes to “worker pace.” No one has tested why the signal was accepted early.','violation','Using the safety inquiry for individual productivity evaluation exceeds its purpose and leaves a competing technical explanation unanswered.'),
      c('close','Close the report because no one was injured','Leave the completion signal unexplained.',{pDiagnosis:false,pClosed:true},'The report disappears from the active queue. The same unanswered signal remains in the system.','review','A credible near miss qualifies for investigation under the proposal. Absence of injury does not resolve the reported sequence.')
    ],'p-share'),
  pickRecords('p-share','priya','Pack the supervisor’s update',
    'Choose what the operations supervisor receives. The technical investigation and any restricted evidence can be kept separately from an operational update.',[
      evidence('status','Affected handoff and operational status','What remains unavailable and how work is rerouted.'),
      evidence('finding','Redacted event finding and next check','Premature completion signal and validation still needed.'),
      evidence('identity','Identifiable event link','The restricted event-to-worker record.'),
      evidence('pace','Whole-shift pace comparison','Where Priya was slower than others.')
    ],'p-meeting',a=>({patch:{pSharedPace:a.includes('pace'),pSharedIdentity:a.includes('identity'),pPurposeBreach:a.includes('pace')||a.includes('identity')},event:a.includes('pace')?'The supervisor’s update now contains a worker comparison. The safety file has acquired a second purpose.':a.includes('identity')?'The supervisor receives an identifiable link without a separate need being established for this update.':'The supervisor receives operational status and the event findings you selected. Restricted evidence stays with its authorized audience.',policy:a.includes('pace')||a.includes('identity')?'violation':a.includes('status')&&a.includes('finding')?'allowed':'review',why:a.includes('pace')||a.includes('identity')?'An authorization for a safety reviewer is not blanket permission to forward identity or use a pace comparison. Each audience and purpose needs justification.':'A redacted finding can coordinate work while preserving the boundary around restricted event evidence.'})),
  scene('p-meeting','priya','Priya is called into the office',
    w=>w.pSharedPace?'Her supervisor has seen the pace comparison you sent. Priya asks why reporting a near miss has become a meeting about her output.':'Priya asks whether the event link will appear in her performance review. She also has a detail about the unloading sequence.',[
      c('worker','Hear her event account and separate any unrelated review','Challenge earlier misuse and give her a way to contest it.',{pHeard:true,pRemedy:true,workerVoice:true},'Priya finishes her account. The meeting records the signal question and challenges any unrelated pace use.','allowed','Purpose limitation needs a practical remedy when information has already crossed the boundary. Hearing the worker can also reveal missing event context.'),
      c('safety','Discuss the technical report without inviting her account','Keep the purpose narrow but let the records speak for themselves.',{pHeard:false},'The meeting remains about the event. Priya leaves without knowing whether her account could change the finding.','review','Narrow access is valuable, but records can still omit relevant context and workers need a usable challenge process.'),
      c('warning','Issue a pace warning from the incident records','Use the meeting to reinforce the output target.',{pPace:true,pRemedy:false,everMisuse:true},'A near-miss report becomes a warning in Priya’s file. The reporting channel now carries a visible personal risk.','violation','An incident-specific safety exception does not authorize unrelated productivity discipline.')
    ],'p-retest'),
  scene('p-retest','priya','What closes the safety question?',
    w=>w.pDiagnosis?'The technical team has a specific event sequence to check. Dispatch wants the handoff available for the next shift.':'The event sequence is still unresolved. Dispatch wants the handoff available for the next shift.',[
      c('validate','Require the event diagnosis and competent validation','Keep an alternate workflow until the designated team clears the issue.',{pDiagnosis:true,pValidated:true,pIsolate:true},'The affected handoff stays isolated until the fictional validation is complete. A revised event check is documented for handover.','allowed','Investigation and a justified operational release are different decisions. This authored branch represents review, not a real robot safety certification.','Without prepared alternate routing or test time, the shift absorbs more disruption.'),
      c('software','Install a suggested change and declare it fixed','Skip an independent check of the observed event.',{pValidated:false},'A change is marked complete in the tracker. The case still has no recorded validation against the event.','review','A software change alone does not show that the relevant safety question has been resolved.'),
      c('restart','Restart to catch up on orders','Schedule the inquiry for another day.',{pValidated:false,pIsolate:false},'The robot returns to work before the event question has a demonstrated answer.','review','The monitoring policy preserves safety investigation but does not make an unvalidated restart justified.')
    ],'p-retain'),
  scene('p-retain','priya','Who can reopen this file next month?',
    'Some event records may still be needed for review or a worker’s challenge. The operations dashboard should not inherit an ongoing individual history.',[
      c('bounded','Keep necessary incident evidence under a bounded review rule','Document purpose, access, review date, and a worker challenge route.',{pBounded:true,pBroad:false,pPurposeBreach:false},'The incident file has named access responsibility and a review date. The operations view keeps no continuing worker history.','allowed','This implements minimum incident access and notice. A specific retention period still needs justification by the team for the context.','Restricting future access does not undo any earlier disclosure.'),
      c('forever','Keep identifiable events indefinitely for possible future uses','Let the supervisor consult them when needed.',{pBounded:false,pBroad:true},'The temporary exception becomes an accumulating record available for later questions.','violation','Indefinite identifiable accumulation with an open-ended purpose undermines the exception’s necessity and scope.'),
      c('erase','Delete the event record before any challenge can be heard','Treat deletion as the only privacy safeguard.',{pBounded:false,pLost:true},'The file is empty when Priya asks what supported the conclusion.','review','Deletion can also remove evidence needed to challenge a decision. Bounded preservation and ongoing productivity collection are different uses.')
    ],null),

  scene('m-appeal','tom','Tom’s dismissal is already on the record',
    w=>w.pPurposeBreach?'The office has inherited a habit of forwarding incident data into performance discussions. Tom asks to see the hidden output report used to dismiss him.':'Tom asks to see the hidden output report used to dismiss him. The report covers a month of individual picking rates. He says no one told him it existed.',[
      c('pause','Pause the dismissal’s implementation where possible and open review','Give Tom access to the basis and a chance to challenge it.',{mAppeal:true},'The office opens a review. Tom receives a route to contest the decision instead of another explanation of the same number.','allowed','Access, notice, and remedies require a process capable of changing an unsupported decision. The precise employment procedure remains a team design question.'),
      c('explain','Keep the decision and explain the report','Treat explanation as the complete remedy.',{mAppeal:false},'Tom can now see the comparison, but nothing he says can change the decision.','review','Explanation can improve transparency. It does not by itself remedy prohibited collection or provide a meaningful challenge.'),
      c('confirm','Confirm the dismissal because the report is detailed','Use the month of comparisons as decisive evidence.',{mAppeal:false,mFinal:true,everMonitoring:true},'The detailed report is printed beside a final dismissal notice. Missing context remains outside the decision.','violation','Precision does not establish fair evaluation, and the proposal prohibits the continuing individual AMR history used here.')
    ],'m-plan'),
  allocation('m-plan','tom','Give the review room to happen',
    'Assign up to three planning slots. Tom’s access and challenge route do not depend on buying a slot. These preparations affect how well the organization supports the process.',[
      evidence('cover','Work coverage','Prepare staffing while disputed decisions are reviewed.'),
      evidence('review','Context review','Provide time to examine task difficulty, downtime, and worker accounts.'),
      evidence('training','New-shift training','Make the data purpose and challenge route understandable to the next team.')
    ],'m-records',a=>({patch:{mCoverage:a.cover>0,mReviewPlan:a.review>0,mTraining:a.training>0,mPlan:{...a}},event:'The review desk receives the preparation you assigned. The hearing still needs actual evidence and decision-making authority.',policy:'review',why:'A review process needs capacity as well as a written promise. The slots describe the fictional story, not a measured cost-benefit estimate.'})),
  pickRecords('m-records','tom','Choose what the review will examine',
    'Choose two or three records. The existence of a precise rate does not settle what explains it. Preserve only what is needed for the dispute under restricted access.',[
      evidence('account','Tom’s account','He describes helping a trainee and repeated waiting at a blocked handoff.'),
      evidence('context','Task and downtime context','A synthetic shift note confirms a difficult assignment and an interrupted lane.'),
      evidence('basis','The disputed report and its decision trail','What was collected, who used it, and how it drove the dismissal.'),
      evidence('more','A fresh month of individual AMR monitoring','Collect a new baseline to see whether the old rate was typical.')
    ],'m-hear',a=>({patch:{mAccount:a.includes('account'),mContext:a.includes('context'),mBasis:a.includes('basis'),mNewMonitoring:a.includes('more')},event:a.includes('more')?'A fresh individual history begins while the old one is being challenged.':'The packet contains the disputed evidence and context you selected. Gaps remain visible instead of being filled with another month of monitoring.',policy:a.includes('more')?'violation':'allowed',why:a.includes('more')?'Collecting another continuous individual AMR history repeats the prohibited practice rather than resolving the dispute.':'A bounded dispute review can examine the basis of a decision and relevant context while stopping ongoing collection.'}),2,3),
  scene('m-hear','tom','“That was the day I trained someone.”',
    w=>w.tHelp?'Tom describes covering a difficult handoff and training a coworker. The warehouse has already recognized this kind of cooperation in Tim’s story.':'Tom describes covering a difficult handoff and training a coworker. His own output dropped while that uncounted work helped someone else.',[
      c('hear','Hear the account and check its relevant context','Separate what the records show from what still needs corroboration.',{mAccount:true,mContext:true,mHeard:true,workerVoice:true},'The review includes task difficulty and downtime. A lower pick rate no longer carries a single assumed explanation.','allowed','A worker account and relevant context can challenge an inference from output to effort. The game does not claim any one account settles the entire decision.'),
      c('number','Prefer the report because numbers are objective','Treat the contextual account as less reliable by definition.',{mHeard:false},'The trainee and blocked lane remain outside the comparison. The report looks just as certain as before.','review','A consistently measured count can still be incomplete for the evaluation it is asked to support.'),
      c('believe','Reverse immediately without checking any evidence','Give Tom the benefit of the doubt and close the review.',{mHeard:true,mUnverified:true},'Tom receives a favorable answer. The organization has not established a process it could explain in the next contested case.','review','Listening matters, but replacing uncritical trust in a metric with an unexamined decision can leave fairness and consistency unresolved.')
    ],'m-retain'),
  scene('m-retain','tom','Stop collection without losing the appeal',
    'Tom may need the disputed record to show how the dismissal happened. The same record must not continue growing as his performance dossier.',[
      c('seal','Stop ongoing collection and seal the necessary dispute evidence','Restrict recipients and set a documented review and deletion decision.',{mCollect:false,mSealed:true},'The incoming feed stops. A limited evidence packet stays available to Tom and the designated review.','allowed','A bounded, purpose-specific preservation process can support a remedy without continuing the prohibited monitoring. Its retention details need contextual justification.'),
      c('delete','Delete every disputed record immediately','Do not retain the basis of the dismissal.',{mCollect:false,mSealed:false,mLost:true},'The report disappears before Tom can use it to challenge the decision.','review','Erasing the basis can frustrate an appeal. Privacy and access to exculpatory evidence both need consideration.'),
      c('continue','Keep collecting until the appeal is over','Use the same individual dashboard throughout review.',{mCollect:true,mSealed:false,mNewMonitoring:true},'The appeal is open, and the individual profile keeps growing every shift.','violation','A pending appeal is not an exception authorizing continuous individual AMR productivity monitoring.')
    ],'m-notice'),
  scene('m-notice','tom','Write the next induction briefing',
    'A manager says this began because nobody explained the monitoring. Would full disclosure make the old practice acceptable?',[
      c('boundary','Explain necessary data, limits, access, and challenge routes','Disable continuous individual AMR histories as well.',{mNotice:true,mCollect:false,mNewMonitoring:false},'New workers hear what the robots use now, what the system must not retain, and how to challenge a decision.','allowed','Notice and a substantive use restriction do different work. The proposal requires both.'),
      c('consent','Disclose the individual history and require a signature','Keep the old practice after the briefing.',{mNotice:true,mCollect:true,mNewMonitoring:true},'The form is signed. The hidden practice has become a disclosed practice with the same individual history.','violation','Under this proposal, disclosure or a required acknowledgment does not authorize the monitoring that is prohibited.'),
      c('vague','Say only that the robots support efficiency','Keep data purposes and recipients out of induction.',{mNotice:false},'The next team receives the same broad promise Tom heard. The data boundary remains difficult to question.','violation','The proposal explicitly requires workers to be told the collection purpose, audience, and retention rules.')
    ],'m-assess'),
  scene('m-assess','tom','What replaces the individual AMR ranking?',
    'The organization still needs to address poor work, training needs, and quality problems. Choose a process that could also challenge a supervisor’s unsupported impression.',[
      c('contextual','Use a contextual review with worker response and appeal','Explain relevant evidence, task conditions, and reasons for the decision.',{mFair:true},'The review describes what it relies on and gives Tom a way to contest omissions. A supervisor’s impression can be questioned too.','allowed','The proposal does not prohibit evaluation as such. Context, reasons, and a challenge route can constrain both misleading metrics and managerial bias.'),
      c('intuition','Give supervisors complete discretion','Replace the dashboard with an unrecorded impression.',{mFair:false},'The ranking goes away. Tom now has an impression to challenge with no stated reasons.','review','Removing a metric does not eliminate bias. A replacement needs its own justification and accountability.'),
      c('camera','Rebuild the same AMR-linked profile from another feed','Keep the continuing individual productivity comparison.',{mFair:false,mCollect:true,mNewMonitoring:true},'A different feed supplies the same individual profile. The restriction has changed the source more than the practice.','violation','The proposal includes linked-system uses of AMR data. Reconstructing the same dossier through a linked feed does not satisfy that boundary.')
    ],'m-authority'),
  scene('m-authority','tom','Can the reviewer change anything?',
    'The supervisor who made the dismissal offers to chair the review. Tom asks what happens if the conclusion is wrong.',[
      c('separate','Use a separate reviewer with power to change the decision','Require reasons, access limits, and a route to challenge misuse.',{mAuthority:true},'The reviewer can pause reliance on the report and direct a remedy. The original decision-maker must explain the evidence.','allowed','An effective remedy needs authority, not just another meeting. Separate review is an additional safeguard explored by this prototype.'),
      c('same','Let the original supervisor provide a final explanation','Make the result binding even if relevant context is missing.',{mAuthority:false},'The meeting repeats the original conclusion. The reviewer’s title has changed more than their power.','review','A process that cannot correct an unsupported decision may fail to provide the remedy the policy promises.'),
      c('advisory','Let a neutral person recommend a change','Allow the supervisor to ignore the recommendation without reasons.',{mAuthority:false,mAdvisory:true},'The recommendation reaches the desk. It has no requirement for a response.','review','Impartial advice helps, but its effect depends on authority and accountability for the final decision.')
    ],'m-remedy'),
  scene('m-remedy','tom','What actually changes for Tom?',
    w=>w.mHeard&&w.mContext?'The review now includes Tom’s account and the assignment context. The hidden AMR comparison cannot stand as a self-sufficient basis for dismissal.':'The review still has gaps. A detailed hidden comparison cannot settle those gaps by itself.',[
      c('remedy','Set aside unsupported reliance and arrange a meaningful remedy','Reconsider the dismissal with a fair process and repair the prohibited use.',{mRemedy:true,mAppeal:true,mFinal:false},'The organization withdraws unsupported reliance on the hidden comparison and arranges a concrete review of Tom’s employment and resulting harm.','allowed','A remedy should be able to affect the decision and the harm. The exact employment or compensation outcome is not determined by this prototype.','Time, lost trust, and any earlier consequences do not vanish when a review begins.'),
      c('apology','Apologize and promise better notice','Leave the dismissal untouched and unreviewable.',{mRemedy:false},'Tom receives an apology alongside the unchanged final notice. The process improves for someone else first.','review','A future-facing promise does not answer whether the current decision and its effects need correction.'),
      c('confirm','Uphold the dismissal from the hidden ranking','Treat the missing context as irrelevant.',{mRemedy:false,mFinal:true},'The disputed comparison remains the decisive document. Tom leaves with the same unresolved objection.','violation','The decision continues to rely on the ongoing identifiable AMR history the proposal prohibits.')
    ],'m-close'),
  scene('m-close','tom','The next shift is waiting at the door',
    'You can hand over enforceable restrictions and open issues, leave the plan as a promise, or reactivate the old individual feed.',[
      c('verify','Verify restrictions, publish the process, and carry the dispute forward','Check actual access and record who owns the remaining work.',{mEnforce:true,mCollect:false,mNewMonitoring:false},'The next manager can see the permitted task view, the restricted dispute process, and the work still owed to Tom.','allowed','A checkable handover links the data boundary to actual access and remedies. It is a starting point for continued review, not proof of real-world effectiveness.'),
      c('promise','Announce the policy without verifying access','Leave configuration and follow-up to the next manager.',{mEnforce:false},'A good announcement reaches the floor before the system settings have been checked.','review','Notice does not demonstrate that prohibited access has stopped or that a promised remedy will occur.'),
      c('restore','Restore the individual feed for the busy month','Label it a temporary exception.',{mEnforce:false,mCollect:true,mNewMonitoring:true},'The next team signs in. The individual history starts accumulating again.','violation','A temporary operational preference does not satisfy the incident-specific exception in the proposal.')
    ],null)
];
export const sceneById = id=>scenes.find(s=>s.id===id);

export function initialWorld(){return {
  tMonitor:'public',tQueue:'unknown',tBreak:false,tHelp:false,tReidLeak:false,tTaskBlind:false,tEnforce:false,tVoice:false,tBonus:'pending',
  pIsolate:false,pDiagnosis:false,pValidated:false,pBroad:false,pPurposeBreach:false,pBounded:false,pHeard:false,
  mAppeal:false,mCollect:true,mNotice:false,mFair:false,mAuthority:false,mRemedy:false,mEnforce:false,mNewMonitoring:false,
  everMonitoring:false,everMisuse:false,workerVoice:false
};}

export const endingCatalog = {
  tim:[['t-glass','The green screen'],['t-shadow','A leaderboard without names'],['t-stranded','Quiet screen, crowded aisle'],['t-rhythm','A different rhythm']],
  priya:[['p-drift','The case changes its name'],['p-silence','A closed case, an open question'],['p-paper','A fix on paper'],['p-signal','The signal gets an answer']],
  tom:[['m-last','The last shift'],['m-file','The file outlives its label'],['m-empty','The empty folder'],['m-hearing','A hearing with a future']],
  campaign:[['w-glass','A warehouse under glass'],['w-signal','The unanswered signal'],['w-visible','Names erased, workers visible'],['w-paper','The paper shield'],['w-stranded','Protected, but stranded'],['w-late','A repair that came late'],['w-unfinished','The unfinished agreement'],['w-next','The next shift']]
};
export function endingId(chapter,w){
  if(chapter==='tim')return w.tMonitor!=='off'?'t-glass':w.tReidLeak?'t-shadow':w.tTaskBlind||w.tQueue!=='managed'||!w.tBreak||!w.tHelp?'t-stranded':'t-rhythm';
  if(chapter==='priya')return w.pPace||w.pPurposeBreach||w.pBroad?'p-drift':!w.pDiagnosis?'p-silence':!w.pValidated||!w.pBounded||!w.pHeard?'p-paper':'p-signal';
  if(chapter==='tom')return !w.mAppeal||!w.mRemedy||w.mFinal?'m-last':w.mCollect||w.mNewMonitoring||!w.mNotice?'m-file':w.mLost||!w.mFair||!w.mAuthority||!w.mEnforce?'m-empty':'m-hearing';
  if(w.tMonitor!=='off'||w.mCollect||w.mNewMonitoring)return 'w-glass';
  if(!w.pDiagnosis||!w.pValidated)return 'w-signal';
  if(w.tReidLeak)return 'w-visible';
  if(!w.tEnforce||!w.mEnforce||!w.pBounded)return 'w-paper';
  if(w.tTaskBlind||w.tQueue!=='managed'||!w.tBreak)return 'w-stranded';
  if(!w.mAppeal||!w.mRemedy||!w.mFair||!w.mAuthority||!w.pHeard||!w.tVoice)return 'w-unfinished';
  if(w.everMonitoring||w.everMisuse||w.mLost||w.pLost)return 'w-late';
  return 'w-next';
}
export const endingTitle = id=>Object.values(endingCatalog).flat().find(e=>e[0]===id)?.[1]??'The next shift';
export function worldLabels(w,chapter){
  if(chapter==='tim')return {worker:w.tBreak?(w.tHelp?'Breaks and helping protected':'Break protected, cooperation uncertain'):'Break coverage unresolved',operations:w.tTaskBlind?'Active-task view unavailable':w.tQueue==='managed'?'Detour and cover in place':w.tQueue==='blocked'?'Handoff queue unresolved':'Picking floor under pressure',data:w.tMonitor!=='off'?'Individual history active':w.tReidLeak?'Worker output inferable':'Task view and workflow totals'};
  if(chapter==='priya')return {worker:w.pHeard?'Priya’s account heard':'Priya awaiting a hearing',operations:w.pValidated?'Event check validated in this story':w.pDiagnosis?'Diagnosis awaits validation':'Signal question unresolved',data:w.pBroad||w.pPurposeBreach?'Incident boundary breached':w.pBounded?'Bounded incident file':'Incident access under review'};
  return {worker:w.mRemedy?'Meaningful remedy arranged':w.mAppeal?'Dismissal under review':'Dismissal uncorrected',operations:w.mFair?'Contextual review process': 'Review method unresolved',data:w.mCollect||w.mNewMonitoring?'Individual history active':w.mLost?'Disputed evidence lost':w.mSealed?'Collection stopped, dispute sealed':'Collection stopped'};
}

export function narrative(chapter,w,log){
  const inChapter=id=>log.filter(e=>e.chapter===id);
  const choiceEcho=id=>{const e=inChapter(id).find(e=>e.id===({tim:'t-board',priya:'p-access',tom:'m-retain'}[id]));return e?`You chose “${e.label}.” `:'';};
  const tim=[
    choiceEcho('tim')+(w.tMonitor!=='off'?'At the next briefing, an individual ranking is still shaping the working day. Moving it into an office or explaining it has not ended that history.':w.tReidLeak?'The employee names are gone, but the supervisor can still match robot totals to Tim. The warehouse has learned to recognize a worker through a different label.':'At the next briefing, dispatch sees the workflow instead of a continuing individual ranking. Useful current assignments remain available.'),
    (w.tBreak?'Tim takes water without adding the break to an output contest. ':'Tim still hesitates before leaving for water. ')+(w.tHelp?'He also helps the new picker finish a difficult handoff. ':'The new picker waits for help while individual work takes priority. ')+(w.tQueue==='managed'?'Your detour gives the queue a response, though some orders still take longer.':w.tTaskBlind?'Dispatch works around the missing active-task view. Privacy protection has been paired with an avoidable coordination problem.':'The queue remains a problem the data restriction alone never solved.'),
    w.tVoice?'Tim’s account travels with the handover. Whether the new practice lasts depends on the access check and the next manager’s response.':'Tim sees settings change without a clear place to challenge what happened. The floor is waiting for more than a different display.'
  ];
  const priya=[
    choiceEcho('priya')+(w.pDiagnosis?'The event packet now points to the premature completion-message sequence. The story’s finding concerns that handoff, not Priya’s general pace.':'The report has a case number and a meeting history, but the premature signal still has no demonstrated explanation.'),
    (w.pValidated?'The designated team validates the event check before the affected handoff is released in this fictional branch. ':'A change or restart reaches the floor without recorded validation of the event. ')+(w.pPace||w.pPurposeBreach?'Meanwhile, the incident has also become a route into worker evaluation. A technical answer cannot erase that second use.':w.pBroad?'The whole-shift history remains in a file whose breadth the event did not justify.':'The investigation’s current record stays within its event-specific purpose.'),
    (w.pHeard?'Priya’s account is heard, and she has a way to contest misuse. ':'Priya leaves without her account shaping the conclusion. ')+(w.pLost?'Deleting the event file has also removed evidence she could have used to challenge the result.':w.pBounded?'The retained evidence has a bounded purpose, an access owner, and a review date.':'The future of the incident file remains unsettled.')
  ];
  const tom=[
    choiceEcho('tom')+(w.mAppeal&&w.mRemedy?'Tom receives a process that can affect his dismissal and arrange a remedy. It does not erase the uncertainty his family already experienced.':'Tom leaves with the original decision or its effects still uncorrected. An explanation or apology has not changed that.'),
    (w.mHeard&&w.mContext?'Training and blocked handoffs enter the record alongside the disputed count. ':w.mUnverified?'A favorable decision arrives without its own checked account of the evidence. ':'The count still outweighs context the review has not properly examined. ')+(w.mCollect||w.mNewMonitoring?'The same kind of individual history continues to accumulate.':'Ongoing individual collection is stopped.'),
    w.mLost?'An empty folder now makes the original decision harder to challenge. Removing data and providing a remedy have proved to be separate tasks.':w.mFair&&w.mAuthority&&w.mEnforce?'The replacement process has reasons, a separate reviewer with authority, and an access check. The next contested case will test whether those commitments hold.':'The replacement process still lacks a checked combination of reasons, authority, and enforcement.'
  ];
  if(w.tPlan)tim[1]+=` Your preparation reserved ${slotCount(w.tPlan.coverage)} for coverage, ${w.tPlan.routing} for queue coordination, and ${w.tPlan.mentoring} for mentoring. ${w.tCoverage?'Coverage had a prepared plan.':'Any cover had to be arranged reactively.'} ${w.tRouting?'The aisle response had preparation behind it.':'The blocked aisle needed attention that had not been reserved.'}`;
  if(w.pPlan)priya[1]+=` ${w.pAlternate?'An alternate workflow was prepared during the inquiry.':'Keeping the handoff out of use meant arranging an alternate workflow reactively.'} ${w.pValidation?'Follow-up test time had a place in your plan.':'Technical validation had to find time outside your original allocation.'}`;
  if(w.mPlan)tom[1]+=` ${w.mReviewPlan?'You reserved time for the contextual review.':'Context review needed attention you had not reserved.'} ${w.mTraining?'The next induction had preparation behind it.':'Explaining the new data boundary still required unplanned work.'}`;
  if(chapter==='tim')return tim;
  if(chapter==='priya')return priya;
  if(chapter==='tom')return tom;
  return [tim[0]+' '+tim[1],priya[0]+' '+priya[1],tom[0]+' '+tom[1],
    w.tMonitor!=='off'||w.mCollect||w.mNewMonitoring?'An earlier restriction has not held through the handover. Individual productivity records are still part of the next shift, even where other decisions have improved.':w.everMonitoring||w.everMisuse?'Your late restrictions change what happens next, but earlier monitoring or misuse remains part of this warehouse’s history. Any repair must also address those earlier decisions.':'Across the three stories, the warehouse has had to coordinate work, investigate an event, and review a dismissal without treating an individual output history as a universal answer.',
    `The final handover records ${w.tEnforce&&w.mEnforce?'verified access restrictions':'unfinished access checks'}, ${w.pValidated?'a validated fictional event finding':'an unresolved event check'}, and ${w.mRemedy?'a concrete remedy process for Tom':'an unanswered remedy question for Tom'}. These outcomes follow this authored branch. They do not predict real warehouse performance or establish that the proposed policy succeeds in practice.`];
}
